add(s,'b','Keyboard is the most commonly used input device to enter data and instructions into the computer directly. Keyboards are almost compulsory part of every computer system. Keyboard has a set of keys like a typewriter. A keyboard has over 100 keys on it. When we press a key a predefined value (code) in the form of electrical signal is sent to the computer to tell it which key is pressed. The keys are arranged in different groups.','کی بورڈ ڈیٹا اور ہدایات کو براہِ راست کمپیوٹر میں داخل کرنے کے لیے سب سے زیادہ استعمال ہونے والا ان پٹ آلہ ہے۔ کی بورڈ تقریباً ہر کمپیوٹر سسٹم کا لازمی حصہ ہوتے ہیں۔ کی بورڈ میں ٹائپ رائٹر کی طرح کلیدوں کا ایک سیٹ ہوتا ہے۔ ایک کی بورڈ پر ۱۰۰ سے زیادہ کلیدیں ہوتی ہیں۔ جب ہم کوئی کلید دباتے ہیں تو برقی اشارے کی شکل میں ایک پہلے سے طے شدہ قدر (کوڈ) کمپیوٹر کو بھیجی جاتی ہے جو بتاتی ہے کہ کون سی کلید دبائی گئی ہے۔ کلیدیں مختلف گروپوں میں ترتیب دی گئی ہیں۔','کیبورډ د دخلولو تر ټولو ډیر کارېدونکې وسیله ده چې ډېټا او لارښوونې مستقیم کمپیوټر ته دننه کوي. کیبورډونه د هر کمپیوټر سیسټم نژدې لازمي برخه ده. کیبورډ د ټایپ رایټر په څېر د کلیدونو یوه ټولګه لري. یو کیبورډ ډیر له ۱۰۰ نه زیات کلیدونه لري. کله چې موږ یو کلی کېنو نو د برېښنايي سیګنال په بڼه یوه مخکې ټاکل شوې ارزښت (کوډ) کمپیوټر ته لېږل کېږي چې وايي کوم کلی کېښودل شوی. کلیدونه په مختلفو ډلو کې ترتیب شوي دي.')
def kb():
    keys=''
    def grp(x,y,w,h,col): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="4" fill="#fff" stroke="{col}" stroke-width="2"/>'
    def row(x,y,n,w,h,gap,col):
        return ''.join(f'<rect x="{x+i*(w+gap)}" y="{y}" width="{w}" height="{h}" rx="2" fill="#f4f4f4" stroke="{col}" stroke-width="1"/>' for i in range(n))
    b=grp(120,70,440,160,'#b33')+grp(570,70,70,80,'#b33')+grp(570,160,70,70,'#b33')+grp(650,70,80,160,'#b33')
    b+=row(128,76,12,28,16,5,'#555')+row(128,114,13,28,22,4,'#555')+row(128,142,13,28,22,4,'#555')+row(128,170,12,30,22,4,'#555')+row(128,198,8,40,22,6,'#555')
    b+=row(575,76,3,18,14,4,'#555')+row(575,166,3,18,14,4,'#555')+row(655,76,3,20,20,6,'#555')+row(655,110,3,20,20,6,'#555')+row(655,144,3,20,20,6,'#555')+row(655,178,3,20,20,6,'#555')
    lbl=[(40,30,'Function Keys',200,70),(280,30,'Special Keys',300,70),(440,30,'Lock Keys',620,70),(30,90,'Numeric Keys',128,120),(130,260,'Normal Keys',300,200),(330,260,'Direction Keys',575,185),(520,260,'Numeric Keypad',690,230)]
    for x,y,t,tx,ty in lbl:
        b+=f'<rect x="{x}" y="{y}" width="{len(t)*7+10}" height="20" fill="#fff" stroke="#111" stroke-width="1"/>'+T(x+(len(t)*7+10)/2,y+14,t,11,'middle',700)+f'<line x1="{x+len(t)*7+10}" y1="{y+10}" x2="{tx}" y2="{ty}" stroke="#111" stroke-width="1"/>'
    return svg(740,300,'Standard keyboard with key groups',b)
s['figures']=[dict(id='cs11-s030-fig1',svg=kb(),caption='Figure 1.19 Standard Keyboard',captionUrdu='شکل ۱.۱۹ معیاری کی بورڈ',captionPashto='انځور ۱.۱۹ معیاري کیبورډ',labels=[lab('Function Keys','فنکشن کیز','فنکشن کلیدونه'),lab('Special Keys','خصوصی کلیدیں','ځانګړي کلیدونه'),lab('Lock Keys','لاک کیز','لاک کلیدونه'),lab('Numeric Keys','عددی کلیدیں','شمېریز کلیدونه'),lab('Normal Keys','عام کلیدیں','عادي کلیدونه'),lab('Direction Keys','سمتی کلیدیں','لوري کلیدونه'),lab('Numeric Keypad','عددی کی پیڈ','شمېریز کیپډ')])]
